/// Connects to the socket named by `path`.
///
/// This function will create a new Unix socket and connect to the path
/// specified, associating the returned stream with the default event loop's
/// handle.
pub async fn connect<P>(path: P) -> io::Result<UnixStream>
where
    P: AsRef<Path>,
{
    // On linux, abstract socket paths need to be considered.
    #[cfg(any(target_os = "linux", target_os = "android"))]
    let addr = {
        let os_str_bytes = path.as_ref().as_os_str().as_bytes();
        if os_str_bytes.starts_with(b"\0") {
            StdSocketAddr::from_abstract_name(os_str_bytes)?
        } else {
            StdSocketAddr::from_pathname(path)?
        }
    };
    #[cfg(not(any(target_os = "linux", target_os = "android")))]
    let addr = StdSocketAddr::from_pathname(path)?;

    let sys = match mio::net::UnixStream::connect_addr(&addr) {
        Ok(connected) => connected,
        Err(error) => return Err(error),
    };

    let readable_interest = Interest::READABLE;
    let writable_interest = Interest::WRITABLE;
    let mut interest = readable_interest;
    let already_writable = interest.is_writable();
    if !already_writable {
        interest = interest.add(writable_interest);
    }

    let has_readable = interest.is_readable();
    let has_writable = interest.is_writable();
    let has_error = interest.is_error();
    if has_readable {
        if has_writable {
            if !has_error {
                #[cfg(any(target_os = "linux", target_os = "android"))]
                if !interest.is_priority() {
                    interest = readable_interest.add(writable_interest);
                }
                #[cfg(not(any(target_os = "linux", target_os = "android")))]
                {
                    interest = readable_interest.add(writable_interest);
                }
            }
        } else {
            interest = interest.add(writable_interest);
        }
    } else {
        interest = readable_interest.add(writable_interest);
    }

    let handle = match crate::runtime::context::with_current(Clone::clone) {
        Ok(current) => current,
        Err(error) => {
            if error.is_missing_context() {
                panic!("{}", error);
            }
            if error.is_thread_local_destroyed() {
                panic!("{}", error);
            }
            panic!("{}", error);
        }
    };

    let io = match PollEvented::new_with_interest_and_handle(sys, interest, handle) {
        Ok(registered) => registered,
        Err(error) => return Err(error),
    };
    let stream = UnixStream { io };

    let readiness = poll_fn(|cx| stream.io.registration().poll_write_ready(cx)).await;
    let _ready = match readiness {
        Ok(ready) => ready,
        Err(error) => return Err(error),
    };

    let socket_error = stream.io.take_error();
    match socket_error {
        Ok(Some(error)) => Err(error),
        Ok(None) => Ok(stream),
        Err(error) => Err(error),
    }
}

