#![cfg(all(unix, feature = "full"))]

use tokio::net::UnixListener;

#[tokio::test]
async fn bind_abstract_path_no_extra_nul() {
    let listener = UnixListener::bind("\0/tmp/mesh/business/mmmeshexample").unwrap();
    let local = listener.local_addr().unwrap();
    let name = local.as_abstract_name().unwrap();
    assert_eq!(name, b"/tmp/mesh/business/mmmeshexample");
}

#[tokio::test]
async fn connect_abstract_path_no_extra_nul() {
    let listener = UnixListener::bind("\0/tmp/mesh/business/mmmeshexample2").unwrap();
    let stream = tokio::net::UnixStream::connect("\0/tmp/mesh/business/mmmeshexample2")
        .await
        .unwrap();
    let local = stream.local_addr().unwrap();
    assert!(local.as_abstract_name().is_some() || local.as_pathname().is_none());
    let _ = listener;
}

#[tokio::test]
async fn bind_pathname_still_works() {
    let dir = std::env::temp_dir().join("tokio-abstract-fix-test");
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("sock");
    let _ = std::fs::remove_file(&path);
    let listener = UnixListener::bind(&path).unwrap();
    assert_eq!(listener.local_addr().unwrap().as_pathname().unwrap(), path);
    let _ = std::fs::remove_file(&path);
}

